import{_ as e,o,c as a,a2 as r}from"./chunks/framework.Wk4ah3nE.js";const p=JSON.parse('{"title":"Privacy","description":"What data this documentation site collects, what the Proxmox VM Autoscale software itself transmits, and where your data goes.","frontmatter":{"title":"Privacy","description":"What data this documentation site collects, what the Proxmox VM Autoscale software itself transmits, and where your data goes.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/privacy.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/privacy.html"}],["meta",{"property":"og:title","content":"Privacy"}],["meta",{"property":"og:description","content":"What data this documentation site collects, what the Proxmox VM Autoscale software itself transmits, and where your data goes."}]]},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":null}'),i={name:"privacy.md"};function s(n,t,h,d,l,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p>Two separate questions: what this website does, and what the software does. Both answers are short.</p><h2 id="this-website" tabindex="-1">This website <a class="header-anchor" href="#this-website" aria-label="Permalink to &quot;This website&quot;">​</a></h2><p>This site is static HTML hosted on <strong>GitHub Pages</strong>. It is built from the repository by GitHub Actions and served by GitHub.</p><h3 id="what-the-site-itself-does" tabindex="-1">What the site itself does <a class="header-anchor" href="#what-the-site-itself-does" aria-label="Permalink to &quot;What the site itself does&quot;">​</a></h3><ul><li><strong>No analytics.</strong> No Google Analytics, no Plausible, no Fathom, no pixel, no tag manager.</li><li><strong>No cookies.</strong> The site sets none.</li><li><strong>No third-party embeds.</strong> No YouTube, no Disqus, no chat widget, no social buttons.</li><li><strong>No fonts loaded from a third party.</strong> Typography uses the fonts already on your device.</li><li><strong>No forms.</strong> Nothing on this site accepts input, so there is nothing to submit.</li><li><strong>Search runs in your browser.</strong> The search index is a static file downloaded with the page; your queries are not sent anywhere.</li><li><strong>Theme preference</strong> (light/dark) is stored in your browser&#39;s <code>localStorage</code>. It stays on your device and is never transmitted.</li></ul><h3 id="what-github-does" tabindex="-1">What GitHub does <a class="header-anchor" href="#what-github-does" aria-label="Permalink to &quot;What GitHub does&quot;">​</a></h3><p>GitHub Pages serves the site, and GitHub logs requests as part of operating that service. GitHub&#39;s own documentation states it collects visitors&#39; IP addresses for security and to keep the service running, retaining them for up to 14 days.</p><p>That processing is GitHub&#39;s, not ours, and we neither receive nor have access to those logs. See the <a href="https://docs.github.com/en/site-policy/privacy-policies/github-privacy-statement" target="_blank" rel="noreferrer">GitHub Privacy Statement</a> and <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages#data-collection" target="_blank" rel="noreferrer">GitHub Pages data collection</a>.</p><h3 id="external-links" tabindex="-1">External links <a class="header-anchor" href="#external-links" aria-label="Permalink to &quot;External links&quot;">​</a></h3><p>Pages link to GitHub, the Proxmox documentation, and a handful of other sites. Following one takes you to a third party with its own policy.</p><h3 id="the-open-graph-image" tabindex="-1">The Open Graph image <a class="header-anchor" href="#the-open-graph-image" aria-label="Permalink to &quot;The Open Graph image&quot;">​</a></h3><p>Social previews reference an image hosted by GitHub (<code>repository-images.githubusercontent.com</code>). It loads only when a platform generates a preview card, not when you read the site.</p><h2 id="the-software" tabindex="-1">The software <a class="header-anchor" href="#the-software" aria-label="Permalink to &quot;The software&quot;">​</a></h2><p>Proxmox VM Autoscale runs on your infrastructure. It has no telemetry, no update check, no crash reporting, and no call home of any kind.</p><h3 id="what-it-connects-to" tabindex="-1">What it connects to <a class="header-anchor" href="#what-it-connects-to" aria-label="Permalink to &quot;What it connects to&quot;">​</a></h3><p>Only what you configure:</p><table tabindex="0"><thead><tr><th>Destination</th><th>When</th><th>Contents</th></tr></thead><tbody><tr><td>Your Proxmox nodes, over SSH</td><td>Every cycle</td><td><code>qm</code> and <code>pvesh</code> commands</td></tr><tr><td>Your Gotify server, over HTTPS</td><td>On scaling actions and errors, if enabled</td><td>Notification text: VMID, host name, usage percentage</td></tr><tr><td>Your SMTP relay</td><td>On scaling actions and errors, if enabled</td><td>The same text, as email</td></tr><tr><td>Your <code>webhook_url</code></td><td>On billing report generation, if configured</td><td>The billing report as JSON</td></tr></tbody></table><p>Every one of those is a host <strong>you</strong> name in <code>config.yaml</code>. The project operates none of them and receives nothing.</p><h3 id="what-it-stores-locally" tabindex="-1">What it stores locally <a class="header-anchor" href="#what-it-stores-locally" aria-label="Permalink to &quot;What it stores locally&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Data</th><th>Location</th><th>Contents</th></tr></thead><tbody><tr><td>Log</td><td><code>/var/log/vm_autoscale.log</code></td><td>Host names, VMIDs, usage figures, actions taken</td></tr><tr><td>Billing state</td><td><code>billing_data.json</code> in <code>csv_output_dir</code></td><td>Timestamped CPU and RAM specs per VM</td></tr><tr><td>Billing reports</td><td>CSV in <code>csv_output_dir</code></td><td>Costed period summaries</td></tr><tr><td>Configuration</td><td><code>config.yaml</code></td><td><strong>Your credentials, in plain text</strong></td></tr></tbody></table><p>All of it stays on your machine. Nothing is uploaded, and there is no retention policy beyond what you set — the log does not rotate on its own and the billing file is never pruned. See <a href="/proxmox-vm-autoscale/guide/operations.html#log-rotation">operations</a>.</p><h3 id="if-you-run-it-for-customers" tabindex="-1">If you run it for customers <a class="header-anchor" href="#if-you-run-it-for-customers" aria-label="Permalink to &quot;If you run it for customers&quot;">​</a></h3><p>The billing data records how much CPU and RAM each VM held over time, which for a hosting provider is customer information. Your obligations under GDPR or equivalent law are yours, not this project&#39;s: it is software you run, not a service anyone operates for you.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions about this page, or about the project&#39;s handling of data: <strong><a href="mailto:fabrizio.salmi@gmail.com" target="_blank" rel="noreferrer">fabrizio.salmi@gmail.com</a></strong>.</p><p>Security issues: <a href="/proxmox-vm-autoscale/security/disclosure.html">responsible disclosure</a>, not email to the address above without reading that page first.</p><hr><p><em>Last reviewed: September 2026. Changes to this page are tracked in the <a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/commits/main/docs/privacy.md" target="_blank" rel="noreferrer">repository history</a>.</em></p>',29)])])}const m=e(i,[["render",s]]);export{p as __pageData,m as default};
